+    margin-bottom: 0.25rem;
+  }
+
+  .navbar .nav-link {
+    padding: 0.6rem 0.75rem !important;
+  }
+}
+
+/* Hero Section */
+.hero-image-full {
+  background-size: cover;
+  background-position: center;
+  background-repeat: no-repeat;
+  position: relative;
+  min-height: 480px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.hero-overlay {
+  background: linear-gradient(180deg, rgba(12, 30, 51, 0.62) 0%, rgba(12, 30, 51, 0.78) 100%);
+  width: 100%;
+  height: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.display-heading {
+  font-size: clamp(2.2rem, 5vw, 3.4rem);
+  font-weight: 800;
+  line-height: 1.15;
+  letter-spacing: -0.025em;
+  color: #ffffff;
+  margin-bottom: 1rem;
+  overflow-wrap: break-word;
+}
+
+/* Buttons */
+.btn-brand {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 0.5rem;
+  padding: 0.75rem 1.6rem;
+  font-size: 1rem;
+  font-weight: 600;
+  border-radius: 8px;
+  background-color: var(--primary);
+  border-color: var(--primary);
+  color: #ffffff;
+  text-decoration: none;
+  transition: all 0.2s ease-in-out;
+  box-shadow: 0 4px 14px rgba(2, 132, 199, 0.28);
+}
+
+.btn-brand:hover,
+.btn-brand:focus {
+  background-color: var(--primary-hover);
+  border-color: var(--primary-hover);
+  color: #ffffff;
+  transform: translateY(-2px);
+  box-shadow: 0 6px 18px rgba(2, 132, 199, 0.38);
+}
+
+.btn-brand:active {
+  transform: translateY(0);
+}
+
+/* About Section */
+.section-about {
+  background-color: var(--bg-surface);
+  position: relative;
+}
+
+.section-title {
+  color: var(--dark);
+  font-size: clamp(1.8rem, 3.5vw, 2.4rem);
+  line-height: 1.25;
+}
+
+.about-img {
+  width: 100%;
+  max-width: 520px;
+  height: 360px;
+  object-fit: cover;
+  border-radius: 14px;
+  box-shadow: 0 12px 32px rgba(12, 30, 51, 0.1);
+}
+
+.feature-list li {
+  font-size: 0.98rem;
+  color: var(--text-main);
+  line-height: 1.5;
+}
+
+.check-icon {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 24px;
+  height: 24px;
+  border-radius: 50%;
+  background-color: var(--accent);
+  color: var(--primary);
+  font-weight: 700;
+  font-size: 0.85rem;
+  margin-right: 0.75rem;
+  flex-shrink: 0;
+}
+
+/* Services Section */
+.section-services {
+  background-color: var(--bg-services);
+  position: relative;
+}
+
+.card-service {
+  background-color: var(--bg-surface);
+  border: 1px solid var(--card-border);
+  border-top: 4px solid var(--primary);
+  border-radius: 12px;
+  height: 100%;
+  min-height: 170px;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  transition: transform 0.25s ease, box-shadow 0.25s ease;
+  box-shadow: 0 4px 16px rgba(12, 30, 51, 0.05);
+}
+
+.card-service:hover {
+  transform: translateY(-4px);
+  box-shadow: 0 12px 28px rgba(2, 132, 199, 0.16);
+}
+
+.card-service h6 {
+  color: var(--dark);
+  font-size: 1.05rem;
+  min-height: 2.6rem;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  margin-bottom: 0.5rem;
+}
+
+.card-service p {
+  color: var(--text-muted);
+  line-height: 1.5;
+}
+
+/* Testimonials */
+.section-testimonial {
+  background-color: var(--bg-surface);
+  position: relative;
+}
+
+.testimonial-card {
+  background-color: var(--bg-app);
+  border: 1px solid var(--card-border);
+  box-shadow: 0 6px 20px rgba(12, 30, 51, 0.04);
+}
+
+.testimonial-card p.fs-4 {
+  color: var(--dark);
+  font-family: var(--font-headings);
+  line-height: 1.5;
+  font-weight: 500;
+}
+
+/* Contact / Dark Hero Section */
+.hero-dark {
+  background-color: var(--dark);
+  color: #ffffff;
+  position: relative;
+}
+
+.hero-dark h2 {
+  font-size: clamp(1.9rem, 4vw, 2.5rem);
+}
+
+/* Footer */
+.app-footer {
+  background-color: var(--dark-surface);
+  color: #ffffff;
+  border-top: 1px solid rgba(255, 255, 255, 0.06);
+}
+
+/* Global Images & Badges */
+img {
+  max-width: 100%;
+  height: auto;
+}
+
+.badge-theme {
+  background-color: var(--primary);
+  display: inline-block;
+  padding: 6px 14px;
+  border-radius: 20px;
+  font-size: 0.85rem;
+  color: #ffffff;
+  font-weight: 600;
+  letter-spacing: 0.03em;
+}
+
+/* Responsive adjustments */
+@media (max-width: 767.98px) {
+  .hero-image-full {
+    min-height: 420px;
+  }
+
+  .about-img {
+    height: 260px;
+    max-width: 100%;
+    margin-top: 0.5rem;
+  }
+
+  .card-service {
+    min-height: auto;
+    padding: 1.5rem !important;
+  }
+
+  .card-service h6 {
+    min-height: auto;
+  }
+
+  .hero-image-full .btn-brand,
+  .hero-dark .btn-brand {
+    width: 100%;
+  }
+}
